<?php
require __DIR__.'/portal_positive.php';
require APPPATH.'services/CompanyNativeContacts.php';
foreach(['title'=>'varchar(100)','direction'=>'varchar(3)','last_login'=>'datetime','profile_image'=>'varchar(191)'] as $field=>$type)if(!$db->field_exists($field,$p.'contacts'))$db->query('ALTER TABLE '.$p.'contacts ADD '.$field.' '.$type);
$id=$db->driver()==='sqlite'?'INTEGER PRIMARY KEY AUTOINCREMENT':'INT NOT NULL AUTO_INCREMENT PRIMARY KEY';
if(!$db->table_exists($p.'contact_permissions'))$db->query("CREATE TABLE {$p}contact_permissions(id $id,userid int NOT NULL,permission_id int NOT NULL)");
$native=new CompanyNativeContacts($db,$p);
$values=['firstname'=>'Native','lastname'=>'Contact','email'=>'native@example.invalid','title'=>'Owner contact','phonenumber'=>'000000000','direction'=>'ltr','is_primary'=>'on','permissions'=>['1','6'],'invoice_emails'=>'invoice_emails','project_emails'=>'project_emails','password'=>'Synthetic-password-only-123'];
$na=$native->save($a,7,101,$values,fn($v)=>password_hash($v,PASSWORD_DEFAULT));
$nb=$native->save($b,7,202,$values,fn($v)=>password_hash($v,PASSWORD_DEFAULT));
essentialCheck($na!==$nb,'native contacts allow same email only in separate issuers');
$loaded=$native->get($a,7,101,$na);essentialCheck(!isset($loaded['contact']['password'])&&$loaded['permissions']===[1,6]&&$loaded['contact']['title']==='Owner contact','native form DTO contains fields and permissions, never password hash');
$sessionA=$portal->login($a,$values['email'],$values['password'],'password_verify');$sessionB=$portal->login($b,$values['email'],$values['password'],'password_verify');
essentialCheck($sessionA!==null&&$sessionB!==null&&$portal->sessionIdentity($sessionA,$b)===null,'native password remains issuer-bound despite matching emails/passwords');
essentialThrows(fn()=>$native->get($b,7,101,$na),'company_client_access_denied','shared identity does not expose native contacts');
essentialThrows(fn()=>$native->get($a,7,101,$nb),'company_client_access_denied','contact ID must match client owner');
$edit=$values;$edit['password']='';$edit['title']='Edited title';
$native->save($a,7,101,$edit,fn($v)=>password_hash($v,PASSWORD_DEFAULT),$na,$loaded['revision']);
essentialThrows(fn()=>$native->save($a,7,101,$edit,'password_hash',$na,$loaded['revision']),'company_client_stale','native contact revision guards all fields/permissions');
$loaded=$native->get($a,7,101,$na);$before=$loaded;
$db->failOn='INSERT INTO '.$p.'issuers_audit';$edit['title']='Rollback title';
essentialThrows(fn()=>$native->save($a,7,101,$edit,fn($v)=>password_hash($v,PASSWORD_DEFAULT),$na,$loaded['revision']),'issuer_storage_failed','native contact audit failure rolls back all fields/permissions');$db->failOn=null;
essentialCheck($native->get($a,7,101,$na)===$before,'native contact and revision unchanged after rollback');
$edit['email']='changed-native@example.invalid';$edit['password']='New-synthetic-password-456';
$native->save($a,7,101,$edit,fn($v)=>password_hash($v,PASSWORD_DEFAULT),$na,$before['revision']);
essentialCheck($portal->sessionIdentity($sessionA,$a)===null&&$portal->sessionIdentity($sessionB,$b)!==null,'A password/email update revokes only A session');
essentialThrows(fn()=>CompanyNativeContacts::normalize($values+['userid'=>202]),'company_contact_invalid_input','native contact forbids foreign client field');
$bad=$values;$bad['permissions']=[];
essentialThrows(fn()=>CompanyNativeContacts::normalize($bad),'company_contact_permission_denied','email notification cannot bypass resource permission');
$bad=$values;$bad['password']='short';essentialThrows(fn()=>CompanyNativeContacts::normalize($bad),'company_contact_invalid_input','native contact credential minimum enforced');
echo "Native contact fields, permissions, password and A/B identity tests passed.\n";
if(!$db->field_exists('registration_confirmed',$p.'clients'))$db->query('ALTER TABLE '.$p.'clients ADD registration_confirmed INT NOT NULL DEFAULT 1');
if(!$db->field_exists('country',$p.'clients'))$db->query('ALTER TABLE '.$p.'clients ADD country INT NOT NULL DEFAULT 0');
$meta=$native->metadata($a,7,101);essentialCheck($meta['total']>=1&&$meta['primary_count']===1,'native modal metadata is owner-bound');
$page=$native->page($a,7,101,['draw'=>'1','start'=>'0','length'=>'25','search'=>['value'=>'changed-native'],'order'=>[['column'=>'1','dir'=>'asc']]]);
essentialCheck($page['recordsFiltered']===1&&$page['rows'][0]['id']==$na&&!isset($page['rows'][0]['password']),'native contact table preserves projection and pagination without password data');
essentialThrows(fn()=>$native->page($b,7,101,[]),'company_client_access_denied','shared customer grants no contact table');
essentialCheck($native->emailAvailable($a,7,101,'unused@example.invalid')&&!$native->emailAvailable($a,7,101,'changed-native@example.invalid'),'native email availability uses issuer ownership');
essentialThrows(fn()=>$native->emailAvailable($a,7,101,'unused@example.invalid',$nb),'company_client_access_denied','email validator rejects foreign contact id');
$rev=$native->get($a,7,101,$na)['revision'];$native->setActive($a,7,101,$na,false,$rev);
essentialCheck((int)$native->get($a,7,101,$na)['contact']['active']===0,'native contact status changes only selected owner');
essentialThrows(fn()=>$native->setActive($a,7,101,$na,true,$rev),'company_client_stale','status update requires fresh revision');
$rev=$native->get($a,7,101,$na)['revision'];$db->query("UPDATE {$p}clients SET registration_confirmed=0 WHERE userid=101");
essentialThrows(fn()=>$native->setActive($a,7,101,$na,true,$rev),'company_contact_registration_required','pending registration cannot be activated through switch');
$db->query("UPDATE {$p}clients SET registration_confirmed=1 WHERE userid=101");$native->setActive($a,7,101,$na,true,$rev);
essentialCheck((int)$native->get($b,7,202,$nb)['contact']['active']===1,'A status leaves B contact active');
echo "Native contact paging, email availability and revisioned status passed.\n";
$rev=$native->get($a,7,101,$na)['revision'];$before=$native->get($a,7,101,$na);
$input=$edit;$input['password']='';$input['title']='Must rollback callback';
essentialThrows(fn()=>$native->save($a,7,101,$input,fn($v)=>password_hash($v,PASSWORD_DEFAULT),$na,$rev,static function(){throw new DomainException('company_portal_sender_required');}),'company_portal_sender_required','missing owned mail config rolls back contact save, never sends via global fallback');
essentialCheck($native->get($a,7,101,$na)===$before,'contact post-write participant failure is atomic');

$db->query('UPDATE '.$p.'clients SET active=0 WHERE userid=101');$inactiveRead=$native->get($a,7,101,$na);essentialCheck($inactiveRead['contact']['id']===$na,'inactive customer retains authorized contact inspection');essentialThrows(fn()=>$native->save($a,7,101,$edit,'password_hash',$na,$inactiveRead['revision']),'company_client_access_denied','inactive customer remains closed to contact mutation');$db->query('UPDATE '.$p.'clients SET active=1 WHERE userid=101');
